class LargeResource {
private:
    int* data_;
public:
    explicit LargeResource(size_t s) : data_(new int[s]) {}
    ~LargeResource() { delete[] data_; }

    // Disable Copying (Focus on Move)
    LargeResource(const LargeResource&) = delete;

    // Move Constructor: Stealing the Resource
    LargeResource(LargeResource&& other) noexcept
        : data_(std::exchange(other.data_, nullptr)) {}

    // Move Assignment Operator
    LargeResource& operator=(LargeResource&& other) noexcept {
        if (this != &other) {
            delete[] data_; // Release existing resource
            data_ = std::exchange(other.data_, nullptr); // Steal & nullify source
        }
        return *this;
    }
};
